def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The full-width/full-height line is the separator.
    sep = None
    axis = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            sep, axis = r, "h"
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1:
                sep, axis = c, "v"
                break
    if sep is None:
        return [row[:] for row in grid]
    color = grid[sep][0] if axis == "h" else grid[0][sep]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] not in (bg, color)]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r,c in points), max(r for r,c in points)
    c0, c1 = min(c for r,c in points), max(c for r,c in points)
    out = [row[:] for row in grid]
    if axis == "h":
        # Move the object's bounding rectangle next to the separator.
        if r0 > sep:
            dr = sep + 1 - r0
            far = r1 + dr + 1
        else:
            dr = sep - 1 - r1
            far = r0 + dr - 1
        box = [grid[r][c0:c1+1] for r in range(r0, r1+1)]
        for r in range(r0, r1+1):
            for c in range(c0, c1+1): out[r][c] = bg
        for i, row in enumerate(box):
            rr = r0 + dr + i
            if 0 <= rr < h:
                out[rr][c0:c1+1] = row[:]
        if 0 <= far < h:
            out[far] = [8] * w
    else:
        if c0 > sep:
            dc = sep + 1 - c0
            far = c1 + dc + 1
        else:
            dc = sep - 1 - c1
            far = c0 + dc - 1
        box = [ [grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c] = bg
        for i in range(r0,r1+1):
            for j in range(c0,c1+1):
                cc = j + dc
                if 0 <= cc < w: out[i][cc] = grid[i][j]
        if 0 <= far < w:
            for r in range(h): out[r][far] = 8
    return out
